/* แกะ บริษัท + วันที่ จากหัวข้อเมล
   ตัวอย่าง: 'Fwd: AT4 ส่งตรวจบัญชีฝาก - ถอนและไฟล์ต่างๆ ประจำวันที่ 20-07-69 เรียบร้อยครับ'
              'Fwd: SK8 ส่งตรวจบัญชีเพิ่มเติมประจำวันที่ 18-07-69 เรียบร้อยครับ'  */
const COMPANIES = ['AT4', 'SK8', 'FR8', 'MC8', 'AZ8', 'CY8'];

function parseSubject(subject) {
  const s = String(subject || '');
  let company = null;
  for (const c of COMPANIES) if (new RegExp('\\b' + c + '\\b', 'i').test(s)) { company = c; break; }
  if (!company) {
    const m = s.match(/(?:Fwd:\s*)?\b([A-Z]{2,4}\d{0,2})\b/);
    if (m) company = m[1].toUpperCase();
  }
  let businessDate = null;
  const d = s.match(/(\d{1,2})-(\d{1,2})-(\d{2,4})/);
  if (d) {
    let y = Number(d[3]);
    if (y < 100) y += 2500;      // 69 -> 2569
    if (y > 2400) y -= 543;      // พ.ศ. -> ค.ศ.
    businessDate = `${y}-${String(d[2]).padStart(2, '0')}-${String(d[1]).padStart(2, '0')}`;
  }
  return { company, businessDate, isSupplement: /เพิ่มเติม/.test(s) };
}

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const headers = j.headers || {};
  const subject = j.Subject || j.subject || headers.subject || '';
  const meta = parseSubject(subject);
  const binaryKeys = Object.keys(item.binary || {});

  out.push({
    json: {
      gmail_message_id: j.id,
      gmail_thread_id: j.threadId,
      mailbox: headers.to || j.to || '',
      label: 'AUDIT 2',
      subject,
      sender: headers.from || j.From || j.from || '',
      received_at: j.internalDate ? new Date(Number(j.internalDate)).toISOString() : new Date().toISOString(),
      company: meta.company,
      business_date: meta.businessDate,
      is_supplement: meta.isSupplement,
      file_count: binaryKeys.length,
      status: 'new',
      binaryKeys
    },
    binary: item.binary
  });
}
return out;

/* จับคู่ batch_id ที่ Supabase คืนมา กลับเข้ากับ binary ของเมลเดิม
   แล้วแตกไฟล์แนบเป็นทีละ item (1 item = 1 ไฟล์)  */
const batches = $input.all();
const source = $('แกะบริษัทและวันที่จากหัวข้อ').all();
const out = [];

batches.forEach((b, i) => {
  const rows = Array.isArray(b.json) ? b.json : (b.json.body || [b.json]);
  const row = Array.isArray(rows) ? rows[0] : rows;
  const src = source[i];
  if (!src) return;
  const keys = Object.keys(src.binary || {});
  keys.forEach((k) => {
    const bin = src.binary[k];
    out.push({
      json: {
        batch_id: row.id,
        business_date: src.json.business_date,
        company: src.json.company,
        gmail_message_id: src.json.gmail_message_id,
        file_name: bin.fileName || k,
        mime_type: bin.mimeType || 'application/octet-stream',
        is_zip: /\.zip$/i.test(bin.fileName || k)
      },
      binary: { data: bin }
    });
  });
});
return out;

/* หลังแตก zip จะได้ binary หลายตัวใน item เดียว -> แยกเป็นทีละไฟล์
   และตัดไฟล์ระบบของ macOS ทิ้ง  */
const OK = /\.(xlsx|xlsm|xls|csv|txt|pdf|docx)$/i;
const out = [];
for (const item of $input.all()) {
  const parent = item.json;
  for (const [key, bin] of Object.entries(item.binary || {})) {
    const name = bin.fileName || key;
    if (/^__MACOSX|\/\._|^\._|\.DS_Store$/.test(name)) continue;
    if (!OK.test(name)) continue;
    out.push({
      json: {
        batch_id: parent.batch_id,
        business_date: parent.business_date,
        company: parent.company,
        file_name: name.split('/').pop(),
        from_zip: parent.file_name,
        mime_type: bin.mimeType || 'application/octet-stream'
      },
      binary: { data: bin }
    });
  }
}
return out;

/* เดาชนิดไฟล์จากชื่อ ให้แอปเลือกตัวอ่านได้ถูกตั้งแต่แรก
   และประกอบ path ที่จะเก็บใน Storage  */
function kindOf(name) {
  const n = String(name || '');
  if (/\.pdf$/i.test(n)) return /ฝาก\s*-\s*ถอน|statement|stm/i.test(n) ? 'stm_pdf' : 'doc_clarify';
  if (/\.docx?$/i.test(n)) return 'doc_clarify';
  if (/รายงานบัญชี(ฝาก|ถอน)/.test(n)) return 'bo_main';
  if (/ฝากมือ.*เครดิต/.test(n)) return 'manual_credit';
  if (/ฝากมือ.*Payment/i.test(n)) return 'manual_payment';
  if (/ฝากมือ.*โบนัส/.test(n)) return 'manual_bonus';
  if (/ขอถอนค่าคอม/.test(n)) return 'comm_req';
  if (/ถอนเครดิต/.test(n)) return 'credit_out';
  return 'unknown';
}

const safe = (s) => String(s || '').replace(/[\\/:*?"<>|#]/g, '_').replace(/\s+/g, ' ').trim();

return $input.all().map((item) => {
  const j = item.json;
  const date = j.business_date || 'unknown-date';
  const company = j.company || 'UNKNOWN';
  const path = `${date}/${company}/${safe(j.file_name)}`;
  const bin = (item.binary || {}).data || {};
  return {
    json: {
      ...j,
      kind: kindOf(j.file_name),
      storage_path: path,
      size_bytes: bin.fileSize ? Number(String(bin.fileSize).replace(/[^0-9]/g, '')) : null,
      drive_folder_name: `${date} ${company}`
    },
    binary: item.binary
  };
});
